function convertInput(data, options) {
    options = options || {};
    var type = typeof (data);

    if (Object.prototype.toString.call(data) == '[object Array]') {
        var list = "{\"L\": [";

        for (var i = 0; i < data.length; i++) {

            if (i == 0) {
                list = list + convertInput(data[i], options);
            } else {
                list = list + "," + convertInput(data[i], options);
            }
        }
        list = list + "]}"
        return list;
    } else if (Object.prototype.toString.call(data) == '[object Null]' || type === 'null') {
        return "{\"NULL\": true }";
    } else if (type === 'object') {
        var map = "{\"M\": {";
        var t = 0;
        for (var key in data) {
            if (t == 0) {
                map = map + "\"" + key + "\":" + convertInput(data[key], options);
            } else {
                map = map + ",\"" + key + "\":" + convertInput(data[key], options);
            }
            t++;
        }
        map = map + "}}";
        return map;
    } else if (type === 'string') {
        //if (data.length === 0 && options.convertEmptyValues) {
        if (data.length === 0) {
            return convertInput(null);
        }
        var testdata = "[" + data + "]";

        if (!IsJsonString(testdata)) {
            data = addslashes(data);
        }
        return "{\"S\":\"" + data + "\"}";
    } else if (type === 'number') {
        return "{\"N\":\"" + data + "\"}";

    } else if (type === 'boolean') {
        return "{\"BOOL\":" + data + "}";
    }
}

function IsJsonString(str) {
    try {
        JSON.parse(str);
    } catch (e) {
        return false;
    }
    return true;
}

function addslashes(string) {
    return string.replace(/\\/g, '\\\\').
            replace(/\u0008/g, '\\b').
            replace(/\t/g, '\\t').
            replace(/\n/g, '\\n').
            replace(/\f/g, '\\f').
            replace(/\r/g, '\\r').
            replace(/"/g, '\\"');
}

