    var branchStore = function () {
        var store = new Ext.data.JsonStore({
            method: 'post',
            proxy: new Ext.data.HttpProxy({
                url: modURL + '&op=listBranch',
                method: 'post'
            }),
            fields: ['br_ID','br_Name','br_District','br_State','br_Address','br_Fax',
                'br_Email','br_Phone','br_Incharge','br_status','company','branch_shortname','comp_id','br_pincode','br_Lat','br_Lng','branchIsCPD','branchCpd'],
            totalProperty: 'totalCount',
            root: 'data',
            remoteSort: true,
            autoLoad: false
        });
        store.setDefaultSort('br_Name','ASC');
        return store;
    };

