    var addOrEditParty = function (id,fname,lname) {


        var vendortype = (partytype == 1) ? 'Vendor' : 'Customer';
        var title = (id == 0) ? 'Add ' + vendortype : 'Edit ' + vendortype;
        var PartyEditPanel = editPartyPanel();
        var partyAddPanel = addPartyForm();
        //var Sc_Window = Ext.getCmp('sc_window');
        // if (Ext.isEmpty(Sc_Window)) {
        new Ext.Panel({
            id: 'sc_window',
            title: title,
            iconCls: '',
            modal: true,
            layout: 'fit',
            width: 360,
            autoHeight: true,
            shadow: false,
            resizable: false,
            items: [PartyEditPanel,partyAddPanel],
            buttons: [{
                    text: 'Save',
                    icon: IMAGE_BASE_PATH + '/default/icons/finascop_disk.png',
                    handler: function () {
                        if (PartyEditPanel.getForm().isValid()) {

                            saveParty(id,fname,lname);
                        } else
                        {
                            Ext.MessageBox.alert("Notification","Please check,Some form entries are not valid.");
                        }


                    }
                },
                {
                    text: 'Close',
                    icon: IMAGE_BASE_PATH + '/default/icons/finascop_cancel.png',
                    handler: function () {
                        PartyEditPanel.getForm().reset();
                    }
                }]
        });
        // }
        if (!Ext.isEmpty(id)) {
            var t = new Date();
            var t_stamp = t.format("YmdHis");
            PartyEditPanel.load({
                url: modURL + '&op=getCustomer_EditData',
                params: {
                    'id': id,
                    fname: fname,
                    lname: lname,
                    apikey: _SESSION.apikey,
                    tstamp: t_stamp
                },
                success: function (frm,action) {

                    var tmp = Ext.decode(action.response.responseText);

                    if (tmp.success == true) {

                        var district_store = Ext.getCmp('district').getStore();

                        district_store.baseParams.st_Id = tmp.data.state_ID;

                        Ext.getCmp('textfieldContactperson').setValue(tmp.data.stpa_ContactPerson);
                        Ext.getCmp('textfieldVendorMobileno').setValue(tmp.data.stpa_MobileNo);
                        Ext.getCmp('textfieldVendorEmailid').setValue(tmp.data.stpa_Email);
                        Ext.getCmp('textfieldVendorPanno').setValue(tmp.data.stpa_PanNo);

                        Ext.getCmp('state').setValue(tmp.data.state_ID);

                        Ext.getCmp('state').setRawValue(tmp.data.state);

                        Ext.getCmp('district').setValue(tmp.data.dst_ID);

                        Ext.getCmp('district').setRawValue(tmp.data.c_district);


                        district_store.load();

                    }
                }
            });
        }
        // Sc_Window.show();
        // Sc_Window.doLayout();
        // Sc_Window.center();
    };

    // edit form submit

    var editDataSubmit = function (cust_id)
    {
        if (cust_id > 0) {
            var cust_id = cust_id;
            var act = 'Update';
        } else {
            var act = 'Insert';
            var cust_id = 'I0';
        }
        var form_data = {
            stpa_Fname: Ext.getCmp('stpa_Fname').getValue(),
            stpa_Lname: Ext.getCmp('stpa_Lname').getValue(),
            stpa_GSTIN: Ext.getCmp('stpa_GSTIN').getValue(),
            stpa_Address: Ext.getCmp('stpa_Address').getValue(),
            stpa_ContactPerson: Ext.getCmp('stpa_ContactPerson').getValue(),
            stpa_MobileNo: Ext.getCmp('stpa_MobileNo').getValue(),
            stpa_Email: Ext.getCmp('stpa_Email').getValue(),
            stpa_PanNo: Ext.getCmp('stpa_PanNo').getValue(),
            stpa_City: Ext.getCmp('stpa_City').getValue(),
            stpa_PINCODE: Ext.getCmp('stpa_PINCODE').getValue(),
            st_id: Ext.getCmp('st_id').getValue(),
            dst_Id: Ext.getCmp('dst_Id').getValue(),
            visit_frequency: Ext.getCmp('visit_frequency').getValue(),
            oncall_delivery: Ext.getCmp('oncall_delivery').getValue(),
            stpa_id: cust_id


        };
        var params = {
            action: act,
            module: 'Finascop_Stock',
            op: 'EditVendorDetails',
            extrainfo: 'Save Vendors - ' + act,
            id: cust_id
        };
        console.log('form_data',form_data);
        console.log('params',params);
        APICall(params,Application.Finascop_Stock.editDataSubmit,form_data);
    };


    // edit the dataform
    var editVendorPartyDetails = function (cust_id) {
        var t = new Date();
        var t_stamp = t.format("YmdHis");
        if (!Ext.isEmpty(Ext.getCmp('stpa_Fname').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('stpa_Lname').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('stpa_Address').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('stpa_City').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('stpa_PINCODE').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('stpa_GSTIN').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('stpa_ContactPerson').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('stpa_MobileNo').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('stpa_Email').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('stpa_PanNo').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('dst_Id').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('st_id').getValue())) {

            Ext.Ajax.request({
                url: modURL + '&op=EditVendorDetails',
                method: 'POST',
                params: {
                    customer_id: cust_id,
                    id: Ext.getCmp('partyId').getValue(),
                    fname: Ext.getCmp('curr_firstname').getValue(),
                    lname: Ext.getCmp('curr_lastname').getValue(),
                    firstname: Ext.getCmp('stpa_Fname').getValue(),
                    lastname: Ext.getCmp('stpa_Lname').getValue(),
                    address: Ext.getCmp('stpa_Address').getValue(),
                    city: Ext.getCmp('stpa_City').getValue(),
                    pincode: Ext.getCmp('stpa_PINCODE').getValue(),
                    gstno: Ext.getCmp('stpa_GSTIN').getValue(),
                    contactperson: Ext.getCmp('stpa_ContactPerson').getValue(),
                    mobile: Ext.getCmp('stpa_MobileNo').getValue(),
                    email: Ext.getCmp('stpa_Email').getValue(),
                    pan: Ext.getCmp('stpa_PanNo').getValue(),
                    dst_Id: Ext.getCmp('dst_Id').getValue(),
                    st_Id: Ext.getCmp('st_id').getValue(),
                    partytype: partytype,
                    apikey: _SESSION.apikey,
                    tstamp: t_stamp
                },
                success: function (response) {

                    var tmp = Ext.decode(response.responseText);

                    if (tmp.success === true) {
                        Ext.MessageBox.alert("Notification",tmp.msg,function (btn) {
                            Ext.getCmp('stpa_Fname').reset();
                            Ext.getCmp('lastname').reset();
                            Ext.getCmp('address').reset();
                            Ext.getCmp('city').reset();
                            Ext.getCmp('pincode').reset();
                            Ext.getCmp('gstno').reset();
                            Ext.getCmp('textfieldContactperson').reset();

                            Ext.getCmp('textfieldVendorMobileno').reset();
                            Ext.getCmp('textfieldVendorEmailid').reset();
                            Ext.getCmp('textfieldVendorPanno').reset();
                            Ext.getCmp('district').reset();
                            Ext.getCmp('StateId').reset();
                            Ext.getCmp('gridpanelPurchaseVendordetails').getStore().reload();
                            // var edit=Ext.getCmp('sc_form').getForm();
                            // console.log(edit);
                            // edit.getForm().reset();
                            Ext.getCmp('panelPurchaseEditvendordetails').hide();
                            Ext.getCmp('tabpanelPurchaseVendor').show();
                            Ext.getCmp('buttonPurchaseVendordetailsSave').hide();
                            Ext.getCmp('buttonPurchaseVendordetailsCancel').hide();


                        });
                        // party_window.close();

                    } else {
                        Ext.MessageBox.alert("Notification",tmp.msg);
                        //party_window.close();
                    }

                },
                failure: function (response) {
                    var tmp = Ext.util.JSON.decode(response.responseText);
                    Ext.MessageBox.alert('Error',tmp.msg);
                }

            });

        }

    };

    //save Party data//
    var saveParty = function (id) {
        WinMask = new Ext.LoadMask(Ext.getCmp('panelPurchaseEditvendordetails').getEl());
        // console.log("my id:",id)
        WinMask.show();
        var t = new Date();
        var t_stamp = t.format("YmdHis");
        //if(id==''||id==0){
        if (!Ext.isEmpty(Ext.getCmp('f_name').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('l_name').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('address_id').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('city_id').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('pincode_plc').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('gst_no').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('Contact_person').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('Vendor_Mobileno').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('Vendor_Emailid').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('Vendor_Panno').getValue()) &&
                !Ext.isEmpty(Ext.getCmp('district_id').getValue())) {
            var form_data = {
                id: Ext.getCmp('party_Id').getValue(),
                fname: Ext.getCmp('curr_first_name').getValue(),
                lname: Ext.getCmp('curr_last_name').getValue(),
                firstname: Ext.getCmp('f_name').getValue(),
                lastname: Ext.getCmp('l_name').getValue(),
                address: Ext.getCmp('address_id').getValue(),
                city: Ext.getCmp('city_id').getValue(),
                pincode: Ext.getCmp('pincode_plc').getValue(),
                gstno: Ext.getCmp('gst_no').getValue(),
                contactperson: Ext.getCmp('Contact_person').getValue(),
                mobile: Ext.getCmp('Vendor_Mobileno').getValue(),
                email: Ext.getCmp('Vendor_Emailid').getValue(),
                pan: Ext.getCmp('Vendor_Panno').getValue(),
                dst_Id: Ext.getCmp('district_id').getValue(),
                partytype: partytype,
                tstamp: t_stamp
            }
        }

        var params = {
            action: 'Insert',
            module: 'finascop_stock',
            op: 'saveParty',
            id: id,
            extrainfo: 'fsr'
        };
        APICall(params,Application.Finascop_Stock.savePartyData,form_data);

        WinMask.hide();


    };

