                            recs_per_page = updateRecsPerPage(Ext.getCmp('mypharmaMedicine'));
                            Ext.getCmp('mypharmaMedicine').store.reload({
                                params: {
                                    start: 0,
                                    limit: recs_per_page
                                }
                            });
